        gorsel: G.tablo(["İlahi kitap", "Gönderildiği peygamber"], [["Tevrat", "Hz. Musa"], ["Zebur", "Hz. Davud"], ["İncil", "Hz. İsa"], ["Kur'an-ı Kerim", "Hz. Muhammed (sav)"]]),
